class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is AppChangeReason) {
      buffer.putUint8(129);
      writeValue(buffer, value.index);
    }    else if (value is IconTreatment) {
      buffer.putUint8(130);
      writeValue(buffer, value.index);
    }    else if (value is AppEntry) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is AppChangeEvent) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is IconStyle) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is DeviceStats) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is StatCapabilities) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is WidgetProviderInfo) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : AppChangeReason.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : IconTreatment.values[value];
      case 131:
        return AppEntry.decode(readValue(buffer)!);
      case 132:
        return AppChangeEvent.decode(readValue(buffer)!);
      case 133:
        return IconStyle.decode(readValue(buffer)!);
      case 134:
        return DeviceStats.decode(readValue(buffer)!);
      case 135:
        return StatCapabilities.decode(readValue(buffer)!);
      case 136:
        return WidgetProviderInfo.decode(readValue(buffer)!);
      default:
        return super.readValueOfType(type, buffer);
    }
  }
}

